CREATE OR REPLACE FUNCTION public.nafes_preserve_attempt_snapshot()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
 if TG_TABLE_NAME='nafes_assessment_attempts' then
  if (to_jsonb(new) - array['answers','events','cursor','section_index','section_started_at','version','session_id','access_hash','lease_until','submitted_at','score','total','percent','section_scores']) is distinct from
     (to_jsonb(old) - array['answers','events','cursor','section_index','section_started_at','version','session_id','access_hash','lease_until','submitted_at','score','total','percent','section_scores']) then
   raise exception 'Attempt snapshot is immutable';
  end if;
 end if;
 if old.submitted_at is not null and to_jsonb(new) is distinct from to_jsonb(old) then
  raise exception 'Submitted attempts are immutable';
 end if;
 return new;
end $function$

CREATE OR REPLACE FUNCTION public.lugati_assessment_adaptive_trigger()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
begin
  if new.submitted_at is not null and new.student_id is not null then
    perform public.lugati_sync_sections_attempt(new.student_id,new.id::text,new.submitted_at,new.rendered_sections,new.answers,'assessment');
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.lugati_attempt_worksheet_sync_trigger()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  old_sid uuid;
  new_sid uuid;
begin
  if tg_op in ('UPDATE','DELETE') then
    old_sid := old.student_id;
  end if;
  if tg_op in ('INSERT','UPDATE') then
    new_sid := new.student_id;
  end if;

  if old_sid is not null and (new_sid is null or old_sid is distinct from new_sid) then
    perform public.lugati_sync_student_worksheets(old_sid);
  end if;
  if new_sid is not null then
    perform public.lugati_sync_student_worksheets(new_sid);
  end if;

  return coalesce(new,old);
end;
$function$

